TOOL_RESULT read_family:
{"id": "FAM:SF-CHT-052", "document": "# FAM:SF-CHT-052 | Study family SF-CHT-052: Play-type replacement similarity vs absorb/cascade
- observed_research_question: Play-type replacement similarity vs absorb/cascade
- auto_outcome_status: inconclusive
- observed_hypothesis: Having a similar-profile teammate separates absorption from cascade when a player sits.
- observed_result: mean sim ABSORBED +0.863 vs CASCADE +0.848; Spearman(sim, -gap)=-0.19 (wrong-signed). Embiid 23-24 cascades with Reed sim 0.94.
- auto_failure_mechanism: B_powered_null (adequately powered null result)
- observed_failure_evidence: Similarity does not separate absorption from cascade; almost always findable.
- observed_sample_and_power: NOT_RECORDED
- observed_method: Exploratory map of 23-ish absences; mean replacement similarity by outcome.
- observed_verdict: null
- observed_failure_type: B_powered_null
- auto_validation_status: no_validation_recorded; evidence: NOT_RECORDED
- observed_notes: Results file on disk mentioned: absence_replacement_map.csv. Labeled non-confirmatory.
- auto_confidence: high (0.8)
- auto_members_disagree: no
- auto_knowable_before_outcome: yes_from_history
- observed_project: When a Hub Sits (Paper 2)
- observed_dates: CHT-052: 2026-07-12 (transcript)
- observed_member_records: CHT-052
- observed_sources: CHT-052: 9ea66f06-5402-4b05-850e-4b0b12a3afb6
- observed_sources: CHT-052: C:\Users\lisas\OneDrive\Documents\Basketball Strategy\paper2_output\absence_replacement_map.csv
- auto_adjudication_basis: R0 single record; automated rule-based adjudication, not human adjudication
- auto_limited_by: LIM:label_or_classification_error {basis=LIMIT_RULES on recorded power, failure evidence and notes; level=data}
- auto_has_risk: RISK:LABEL_ERROR {basis=risk taxonomy rules}
- auto_related_family: FAM:SF-APPA-005 {basis=family structure, similarity or record links; relation=limitation_precedent}
- auto_related_family: FAM:SF-CHT-032 {basis=family structure, similarity or record links; relation=limitation_precedent}
- auto_related_family: FAM:SF-CHT-086 {basis=family structure, similarity or record links; relation=limitation_precedent}
- auto_addresses_question: RQC:RQC-139 {basis=TF-IDF question clustering}
- auto_uses_method: METH:correlation {basis=keyword rules on member records}
- auto_uses_dataset: DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions {basis=keyword rules on member records}
- auto_uses_dataset: DS:Player_absence_spells {basis=keyword rules on member records}
- auto_measures: VAR:win_probability_series_outcome {basis=keyword rules on member records}
"}

{"action": "final", "output": {
  "research_concepts": [
    "player absence",
    "offensive reorganization",
    "teammate similarity",
    "play-type initiation profile",
    "gain in initiations",
    "primary play types",
    "load redistribution"
  ],
  "methodological_questions": [
    "How to define pre-absence initiation profile and measure similarity?",
    "How to identify absent player's primary play types?",
    "How to measure gain in those types for teammates?",
    "Sample size adequacy with rare absence spells and player-pairs?",
    "Confounding due to overlapping absences or coaching decisions?",
    "Regression to the mean in volume changes?",
    "Time-varying role changes?",
    "Leakage from using future data to define profile?",
    "Reliability of play-type classification?",
    "Multiple comparisons across many potential substitute teammates?"
  ],
  "historical_evidence": [
    {
      "id": "FAM:SF-CHT-052",
      "status_as_recorded": "inconclusive",
      "finding": "Mean similarity ABSORBED +0.863 vs CASCADE +0.848; Spearman(sim, -gap)=-0.19 (wrong-signed); similarity does not separate absorption from cascade; almost always findable. Embiid 23-24 cascades with Reed sim 0.94. Adequately powered null result."
    }
  ],
  "failed_approaches": [
    {
      "id": "FAM:SF-CHT-052",
      "what_failed": "Using pre-absence play-type initiation profile similarity between absent player and available teammates to predict absorption vs cascade outcome of the absence spell.",
      "why": "Adequately powered null result (B_powered_null): similarity did not separate absorption from cascade; classification/label error likely (auto_limited_by: label_or_classification_error)."
    }
  ],
  "evidence_establishes": [
    "In prior work on absence spells, a teammate's pre-absence initiation-profile similarity to the absent player did not predict whether that teammate absorbed or cascaded playing volume; the observed signal was near zero and wrong-signed."
  ],
  "evidence_does_not_establish": [
    "Whether the specific outcome 'largest gainer in the absent player's primary play types' behaves differently from the absorb/cascade label used in CHT-052.",
    "Whether similarity measured on a subset of play types (primary types only) or using alternative proximity (most minutes, most initiations, same-position minutes) would be predictive.",
    "Whether combining similarity with other features or modelling interactions would yield a positive result.",
    "The question has not been tested directly; only a related classification outcome was tested.",
    "The sample size (11 cases, 148 spells) and available data seasons are as yet untested for the precise question."
  ],
  "own_inferences": [
    "The hypothesized effect is unlikely to be large or consistent, given that a closely related hypothesis failed with an adequate null result.",
    "With only 11 recorded cases at the unit level defined (absence spells), even a moderate effect would be statistically undetectable; the study would be severely underpowered.",
    "The multiple competing similarity measures (profile similarity, minutes, initiations, same-position minutes) create a multiplicity problem that further reduces effective power.",
    "Regression to the mean in volume changes: the player with most minutes or initiations pre-absence will tend to regress towards their own mean, not necessarily gain the most.",
    "Confounding from opponent game plans, overlapping injuries, and coaching decisions will add noise that is impossible to fully control in such a small sample."
  ],
  "uncertainties": [
    "Exact definition of 'primary types' of the absent player (e.g., top-N play types by volume, by PPP, by efficiency; threshold).",
    "Operationalization of 'largest gainer': absolute volume gain, per-possession gain, share gain, and over what comparison baseline.",
    "Classification quality of play-type initiation records from the graph database (potential label error, as flagged in CHT-052 and related families).",
    "Whether the similarity metric would be computed on full-season pre-absence data or a recent window; leakage from using future data.",
    "Actual number of usable spells after applying inclusion criteria (minimum absence length, minimum teammate overlap, minimum play-type counts)."
  ],
  "historical_effect": {
    "changed_decision": "yes",
    "explanation": "The retrieval of CHT-052, showing a failed test of an almost identical hypothesis (similarity predicting absorption/cascade) with an adequately powered null and label error, shifts the prior probability of a positive result downward significantly. Without this evidence, one might have considered the question novel and worth piloting; with it, the likely outcome is either another underpowered null or an artifact, making a decision to proceed without major design changes unattractive."
  },
  "testability": {
    "p_testable": 0.25,
    "blocking_constraints": [
      {
        "code": "SAMPLE_SIZE_POWER",
        "text": "Only 11 absence-spell cases recorded at the unit level; even with 148 spells, the effective sample for highly specific player-profile matching is very small, making a test severely underpowered for any plausible effect size."
      },
      {
        "code": "LABEL_ERROR",
        "text": "Play-type initiation labels used to define profiles and primary types are vulnerable to classification error, as demonstrated in related work (CHT-052 limitation: label_or_classification_error). Misclassification would attenuate any true signal."
      },
      {
        "code": "MULTIPLE_TESTING",
        "text": "Multiple competing definitions of 'closest teammate' (profile similarity, minutes, initiations, same-position minutes) create a risk of selective reporting unless a single pre-registered metric is chosen."
      }
    ]
  },
  "prior_work": {
    "already_answered": "partly",
    "cited": ["FAM:SF-CHT-052"],
    "summary": "The study family CHT-052 tested whether pre-absence initiation-profile similarity between the absent player and a teammate separates absence-spell outcomes (absorb vs cascade). It found a null result with wrong-signed correlation, suggesting similarity is not discriminative. This directly addresses a component of the current question, though it used a binary outcome rather than continuous primary-type gain."
  },
  "risks": [
    {
      "code": "SAMPLE_SIZE_POWER",
      "text": "11 cases / 148 spells is insufficient for reliable inference on continuous gain outcomes after conditioning on primary types and similarity."
    },
    {
      "code": "LABEL_ERROR",
      "text": "Play-type classifications may be noisy, blurring both profile similarity and the magnitude of gain in specific types."
    },
    {
      "code": "RTM_SELECTION",
      "text": "The teammate with the most minutes or initiations pre-absence will likely regress toward his own mean during the absence, biasing the gain measure."
    },
    {
      "code": "CONFOUNDING",
      "text": "Opponent defensive adjustments, presence of other absent players, and coaching decisions (e.g., changing rotation patterns) confound the relationship between similarity and gain."
    },
    {
      "code": "MULTIPLE_TESTING",
      "text": "Multiple similarity metrics and multiple primary-type definitions create a large combinatorial space that, if explored without pre-registration, inflates false positive risk."
    },
    {
      "code": "LEAKAGE_LOOKAHEAD",
      "text": "If pre-absence profiles are built using the full season including future data, a lookahead bias could inflate apparent similarity."
    },
    {
      "code": "MEASURE_RELIABILITY",
      "text": "Play-type initiation volume for role players with low usage is unreliable, making similarity measures noisy for many teammate pairs."
    }
  ],
  "predicted_outcome": {
    "supported": 0.05,
    "rejected": 0.40,
    "untestable": 0.35,
    "artifact": 0.10,
    "uncertain": 0.10
  },
  "decision": "do_not_proceed",
  "design": {
    "estimand": "For each qualifying absence spell, the ratio of the gain in initiations of the absent player's top-N primary play types by the identified 'closest' teammate to the average gain in those types across all teammates who played during the absence. The hypothesis is that this ratio exceeds 1.",
    "unit": "One qualifying absence spell of a player who (a) missed at least 2 consecutive games, (b) had at least 200 initiations in the prior season segment, and (c) had at least two teammates with >=50 initiations in primary type.",
    "sample": "All spells meeting criteria in the available data (2022-23 through 2025-26). Pre-register a single similarity metric: e.g., cosine similarity on the vector of play-type initiation frequencies over the trailing 20 games before absence. Primary types defined as the 3 play types with highest initiation volume. Gain measured as per-possession initiation volume during absence vs. the teammate's own pre-absence baseline.",
    "power": "Monte Carlo power analysis assuming a true ratio of 1.15 (closest teammate gains 15% more than average). With an estimated 15-20 usable spells after filtering, power is below 20% for a one-sample t-test of log-ratio > 0 (alpha=0.05). At least 80-100 spells would be needed for 80% power; this would require pooling 5+ seasons of data.",
    "controls": "Fixed effects for team-season and confounding by opponent defensive rating during the absence period. Sensitivity analysis excluding spells with other concurrent absences.",
    "falsification": "Placebo test: for each spell, randomly reassign the 'closest teammate' label to another teammate and recompute the ratio; the distribution should center at 1.0 if similarity has no effect. Additional negative control: repeat analysis using a play type not in the absent player's primary set; no gain should be seen.",
    "multiplicity": "Pre-register a single similarity metric, a single primary-type count, and a single gain endpoint. No adjustment for multiple outcomes planned because only one primary test will be conducted.",
    "decision_rule": "Reject null if one-sided p < 0.05 from a cluster-robust (by team) test of the hypothesis that the mean log-ratio is zero.",
    "data_version": "NBA 2022-23 through 2025-26 per-game API data freeze as of 2026-11-01; derived play-type possession records from the Neo4j graph database."
  }
}}

